function loadConfig() {
  const requiredEnv = ['PORT', 'NODE_ENV', 'DB_URI'];
  const missing = requiredEnv.filter(key => !process.env[key]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
  return {
    port: parseInt(process.env.PORT, 10),
    env: process.env.NODE_ENV,
    dbUri: process.env.DB_URI
  };
}

module.exports = { loadConfig };

// 5-Dars: Async File Logger Service
const fs = require('fs').promises;
const path = require('path');

class FileLogger {
  constructor(logFileName = 'app.log') {
    this.filePath = path.join(__dirname, logFileName);
  }

  async appendLog(message) {
    const logLine = `[${new Date().toISOString()}] ${message}\n`;
    await fs.appendFile(this.filePath, logLine, 'utf8');
  }

  async readLogs() {
    return await fs.readFile(this.filePath, 'utf8');
  }
}

module.exports = FileLogger;

